import os
import sys
import io
import zlib
import base64
from typing import Optional

# Compressed binary payload (base64 encoded)
_TEMPLATE_PAYLOAD = """"""

def get_embedded_template_stream() -> io.BytesIO:
    """Returns an in-memory BytesIO stream of the master Excel template."""
    compressed_bytes = base64.b64decode(_TEMPLATE_PAYLOAD.encode("ascii"))
    raw_excel_bytes = zlib.decompress(compressed_bytes)
    return io.BytesIO(raw_excel_bytes)


def resolve_template_path(template_name: str = "Consolidated Report Format.xlsx") -> Optional[str]:
    """
    Resolves the master template location with priority:
    1. Same directory as the running .exe (allowing custom template updates without recompiling)
    2. Embedded PyInstaller bundle directory (sys._MEIPASS)
    3. Local project 'templates/' folder
    4. Project root folder
    5. Current working directory templates folder
    """
    candidates = []
    if getattr(sys, 'frozen', False):
        exe_dir = os.path.dirname(sys.executable)
        candidates.append(os.path.join(exe_dir, template_name))
        candidates.append(os.path.join(exe_dir, "templates", template_name))

    if hasattr(sys, '_MEIPASS'):
        candidates.append(os.path.join(sys._MEIPASS, template_name))
        candidates.append(os.path.join(sys._MEIPASS, "templates", template_name))

    proj_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    candidates.append(os.path.join(proj_root, "templates", template_name))
    candidates.append(os.path.join(proj_root, template_name))
    candidates.append(os.path.join(os.getcwd(), "templates", template_name))

    for path in candidates:
        if os.path.exists(path):
            return path
    return None

